	End   float64 `json:"end"`
}

// Config holds the credentials for AI providers
type Config struct {
	OpenAIKey string
	GoogleKey string
}

func NewProviderFromEnv() (Provider, error) {
	if key := os.Getenv("OPENAI_API_KEY"); key != "" {
