	}
	if key := os.Getenv("GOOGLE_API_KEY"); key != "" {
		return NewGoogleProvider(key), nil
	}
	return nil, fmt.Errorf("no AI provider credentials found in environment (set OPENAI_API_KEY or GOOGLE_API_KEY)")
}

